import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

export async function gate({ referenceDir, submissionDir }) {
  try {
    // Read the pinned test cases
    const testCasesPath = join(referenceDir, 'pinned-test-cases.txt');
    const testCases = readFileSync(testCasesPath, 'utf-8');

    // Create a test runner that uses node:test's built-in test function
    // and captures results via a custom test hook
    const testRunnerCode = `
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { dedupeSorted } from '${submissionDir}/answer.mjs';

let passCount = 0;
let failCount = 0;
const testNames = [];
const failedTests = [];

// Hook into the test function to track execution
const originalTest = test;
globalThis.test = (name, fn) => {
  testNames.push(name);
  try {
    fn();
    passCount++;
  } catch (e) {
    failCount++;
    failedTests.push({ name, error: e.message });
    throw e;
  }
};

// Copy over properties from original test
Object.assign(globalThis.test, originalTest);

${testCases}

// Output results as JSON to a known location
const fs = await import('node:fs');
fs.writeFileSync('${referenceDir}/test-results.json', JSON.stringify({
  passCount,
  failCount,
  testNames,
  failedTests,
  totalTests: testNames.length
}));

process.exit(failCount > 0 ? 1 : 0);
`;

    const runnerPath = join(referenceDir, 'test-runner.mjs');
    writeFileSync(runnerPath, testRunnerCode);

    // Execute the test runner
    return new Promise((resolve) => {
      let stdout = '';
      let stderr = '';

      const proc = spawn(process.execPath, [runnerPath], {
        stdio: ['pipe', 'pipe', 'pipe'],
        timeout: 15000,
        env: {}
      });

      proc.stdout.on('data', (data) => {
        stdout += data.toString();
      });

      proc.stderr.on('data', (data) => {
        stderr += data.toString();
      });

      proc.on('close', (code) => {
        try {
          // Read results from file
          const resultsPath = join(referenceDir, 'test-results.json');
          let results;
          try {
            const resultsJson = readFileSync(resultsPath, 'utf-8');
            results = JSON.parse(resultsJson);
          } catch (e) {
            resolve({
              accept: false,
              reason: `Could not read test results file: ${e.message}`
            });
            return;
          }

          // Verify all tests ran
          const expectedTestCount = 8;
          const totalTestsRun = results.passCount + results.failCount;

          if (totalTestsRun !== expectedTestCount) {
            resolve({
              accept: false,
              reason: `Expected ${expectedTestCount} tests to run, but only ${totalTestsRun} ran (${results.passCount} passed, ${results.failCount} failed). Tests: ${results.testNames.join(', ')}`
            });
            return;
          }

          if (results.failCount === 0 && results.passCount === expectedTestCount) {
            resolve({
              accept: true,
              reason: `All ${expectedTestCount} pinned test cases passed`
            });
          } else {
            const failedList = results.failedTests.map(t => `${t.name}: ${t.error}`).join('; ');
            resolve({
              accept: false,
              reason: `${results.failCount} test(s) failed: ${failedList}`
            });
          }
        } catch (e) {
          resolve({
            accept: false,
            reason: `Error processing results: ${e.message}`
          });
        }
      });

      proc.on('error', (err) => {
        resolve({
          accept: false,
          reason: `Process error: ${err.message}`
        });
